@Override
  public void validatePMode (@Nonnull final IPMode aPMode, @Nonnull final ErrorList aErrorList)
  {
    ValueEnforcer.isTrue (aErrorList.isEmpty (), () -> "Errors in global PMode validation: " + aErrorList.toString ());

    try
    {
      MetaAS4Manager.getPModeMgr ().validatePMode (aPMode);
    }
    catch (final PModeValidationException ex)
    {
      aErrorList.add (_createError (ex.getMessage ()));
    }

    final EMEP eMEP = aPMode.getMEP ();
    final EMEPBinding eMEPBinding = aPMode.getMEPBinding ();

    if ((eMEP == EMEP.ONE_WAY && eMEPBinding == EMEPBinding.PUSH) ||
        (eMEP == EMEP.TWO_WAY && eMEPBinding == EMEPBinding.PUSH_PUSH))
    {
      // Valid
    }
    else
    {
      aErrorList.add (_createError ("An invalid combination of PMode MEP (" +
                                    eMEP +
                                    ") and MEP binding (" +
                                    eMEPBinding +
                                    ") was specified, valid are only one-way/push and two-way/push-push."));
    }

    // Leg1 must be present
    final PModeLeg aPModeLeg1 = aPMode.getLeg1 ();
    if (aPModeLeg1 == null)
    {
      aErrorList.add (_createError ("PMode is missing Leg 1"));
    }
    else
    {
      _checkIfLegIsValid (aPMode, aErrorList, aPModeLeg1);

      if (eMEP.isTwoWay ())
      {
        final PModeLeg aPModeLeg2 = aPMode.getLeg2 ();
        if (aPModeLeg2 == null)
        {
          aErrorList.add (_createError ("PMode is missing Leg 2 and is specified as TWO-WAY"));
        }
        else
        {
          _checkIfLegIsValid (aPMode, aErrorList, aPModeLeg2);
        }
      }
    }
  }

@Test
  public void uploadProduct() throws Exception {
    Set<UploadProductResponse> responseHolder = Sets.newHashSet();
    Set<Throwable> exceptionHolder = Sets.newHashSet();
    AtomicBoolean completed = new AtomicBoolean(false);
    //client stream is as complex as Bidirectional streaming
    StreamObserver<Product> uploadStream = stub.uploadProduct(new StreamObserver<UploadProductResponse>() {
      @Override
      public void onNext(UploadProductResponse value) {
        responseHolder.add(value);
      }

      @Override
      public void onError(Throwable t) {
        exceptionHolder.add(t);
      }

      @Override
      public void onCompleted() {
        completed.compareAndSet(false, true);
      }
    });
    Product product = Product.newBuilder()
        .setProductId(faker.number().randomNumber())
        .setProductName(faker.company().name())
        .setProductPrice(faker.number().randomDouble(2, 10, 100))
        .setProductStatus(ProductStatus.InStock)
        .build();
    ImmutableList
        .of(product, product, product)
        .stream()
        .forEach(prod -> uploadStream.onNext(prod));
    uploadStream.onCompleted();

    while (!completed.get()) {
      Thread.sleep(200);
    }

    assertThat(responseHolder.size()).isEqualTo(1);
    assertThat(exceptionHolder).isEmpty();
    assertThat(completed).isTrue();
    verify(productDao, times(3)).upsertProduct(any());
  }

