public ArrayList<String> searchCerberusMetadata(ArrayList<Map<String, String>> sdbMetadata, String sdbName, String principalName) {

        if (sdbMetadata == null) {
            throw new NullPointerException("SDB Metadata is empty");
        }

        ArrayList<String> owner = new ArrayList<>();

        for (Map<String, String> entry : sdbMetadata) {

            if (entry.get("path").contains(sdbName) && !sdbName.isEmpty()) {
                owner.add(entry.get("owner"));
                if (entry.get("created_by").contains(EMAIL_SYMBOL)) owner.add(entry.get("created_by"));
                if (entry.get("last_updated_by").contains(EMAIL_SYMBOL)
                        && !entry.get("last_updated_by").equals(entry.get("created_by"))) {
                    owner.add(entry.get("last_updated_by"));
                }
                return owner;
            } else {
                if (entry.containsValue(principalName)) {
                    owner.add(entry.get("owner"));
                    if (entry.get("created_by").contains(EMAIL_SYMBOL)) owner.add(entry.get("created_by"));
                    if (entry.get("last_updated_by").contains(EMAIL_SYMBOL)
                            && !entry.get("last_updated_by").equals(entry.get("created_by"))) {
                        owner.add(entry.get("last_updated_by"));
                    }
                    return owner;
                }
            }
        }

        owner.add("No owner found");
        return owner;
    }

protected Map<String, ViolationMetaData> filterAndTruncateViolators(LogProcessorLambdaConfig params,
                                                                        RangeSet<Integer> doNotAutoBlockIpRangeSet,
                                                                        Map<String, ViolationMetaData> violators) {

        Date now = new Date();

        return violators.entrySet().stream()
                    .filter(entry -> TimeUnit.MILLISECONDS.toMinutes(now.getTime() - entry.getValue().getDate().getTime()) < params.getBlacklistDurationInMinutes())
                    .filter(entry -> canAddToAutoBlackList(doNotAutoBlockIpRangeSet, entry.getKey()))
                    .sorted((o1, o2) -> o2.getValue().getMaxRate() - o1.getValue().getMaxRate())
                    .limit(cidrLimitForIpSet)
                    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }

public static String getCommand(String string){
    	int index = string.indexOf("invocabot");

    	// If "invocabot" is not in string.
    	if (index == -1) return null;

    	// If "invocabot" is last word in string.
    	String words[] = string.split(" ");
    	if (words[words.length - 1].equals("invocabot"))
    		return "";

    	// If string is just "invocabot".
    	if (string.equalsIgnoreCase("invocabot")) return "";

    	String output;
    	// Check if "invocabot" exists twice.
    	int endIndex = string.indexOf("invocabot", index + 1);
    	int truncationIndex = index + "invocabot".length() + 1;

    	// If "invocabot" exists once, truncate until end of string.
    	if (endIndex == -1) {
    		output = string.substring(truncationIndex);
    	} 
    	// If "invocabot" exists more than once, truncate at the last word before the next "invocabot".
    	else {
    		output = string.substring(truncationIndex, endIndex - 1);
    	}

    	return output;
    }

