@Override
    public Object exec(Map<String, Object> scope) throws ScriptException {
        if (scope == null) {
            throw new NullPointerException();
        }
        EventEntry measure = Publisher.start(monitoringEventName, scope, null);
        Global global = new Global();
        Context context = ContextFactory.getGlobal().enterContext();
        global.init(context);
        try {
            Scriptable outer = new ScriptableMap(scope);
            outer.setPrototype(scriptScope); // script level context and standard objects included with every box
            outer.setParentScope(null);
            Scriptable inner = context.newObject(outer); // inner transient scope for new properties
            inner.setPrototype(outer);
            inner.setParentScope(global);
            Object result = Converter.convert(script.exec(context, inner));
            measure.setResult(result);
            return result;
        } catch (RhinoException re) {
            if (re instanceof JavaScriptException) { // thrown by the script itself
                throw new ScriptThrownException(Converter.convert(((JavaScriptException)re).getValue()));
            } else { // some other runtime exception encountered
                throw new ScriptException(re.getMessage());
            }
        } finally {
            Context.exit();
            measure.end();
        } 
    }

@Test
    public final void testSpin() {
        logger.debug(new Object(){}.getClass().getEnclosingMethod().getName());

        boolean test = true;

        try {
            this.initRCLjava();
            final Node node = RCLJava.createNode("_" + RCLJavaTest.class.getSimpleName());
            final Publisher<Bool> publisher = node.createPublisher(Bool.class, RCLJavaTest.TEST_TOPIC);

            final Bool msg = new Bool();
            msg.setData(true);

            final RCLFuture<Bool> future = new RCLFuture<Bool>(new WeakReference<Node>(node));
            final Subscription<Bool> subscription = node.createSubscription(
                    Bool.class, RCLJavaTest.TEST_TOPIC, new TestConsumer<Bool>(future));

            final Thread thread = new Thread(new Runnable() {
                @Override
                public void run() {
                    RCLJava.spin(node);
                }
            });
            thread.start();

            while (RCLJava.ok() && !future.isDone()) {
                publisher.publish(msg);
            }

            final Bool value = future.get();
            Assert.assertNotNull(value);

            publisher.dispose();
            subscription.dispose();

            DefaultThreadedExecutor.getInstance().removeNode(node);

            node.dispose();
            this.releaseRCLjava();
        } catch (Exception e) {
            test = false;
        }

        Assert.assertTrue(ERROR_RUNTIME, test);
    }

