public void setViewInfo(ViewInfo viewInfo) throws Exception {
    String resource = viewInfo.getResource();
    byte[] json = viewInfo.toCompressedJson();
    LOG.info("Writtng compressed json for resource : " + resource + " - total bytes " +
             json.length);
    if (viewInfo.hasOnlinePartitions()) {
      String viewPath = this.clusterViewsPath + "/" + resource;
      if (zkClient.get().exists(viewPath, false) != null) {
        zkClient.get().setData(viewPath, json, -1);
      } else {
        zkClient.get().create(viewPath, json, ZK_ACL_LIST, CreateMode.PERSISTENT);
      }
    } else {
      LOG.info("No online partitions for " + resource + " - skipped writing.");
    }
  }

public void rollbackFileSet(String[] args) throws Exception {
    if (args.length > 1) {
      final String fileSet = args[1];
      FileSetInfo fileSetInfo = lockFileSet(zkManager, fileSet);

      // Add shutdown hook to gracefully catch SIGKILL signal
      Runtime.getRuntime().addShutdownHook(new Thread(new Runnable() {
        @Override
        public void run() {
          try {
            unlockFileSet(zkManager, fileSet);
          } catch (Exception e) {
            e.printStackTrace();
          }
        }
      }));

      try {
        int versionIndex = selectFileSetRollbackVersion(fileSetInfo, System.in);
        if (confirmFileSetRollbackVersion(fileSet, fileSetInfo, versionIndex, System.in)) {
          rollbackFileSet(zkManager, fileSet, fileSetInfo, versionIndex);
        } else {
          System.out.println("exiting rollback...");
        }
      } catch (IllegalArgumentException exception) {
        LOG.error(exception.getMessage());
      }
    } else {
      System.err.println("missing file set argument");
    }
  }

