public static Term findTerm(String termName) {
		// normalise termName
		String normTermName;
		if (termName == null || StringUtils.isBlank(normTermName = normaliseTerm(termName))) {
			return null;
		}
		// try known term enums first
		Term term = findTermInEnum(normTermName, DwcTerm.values(),
				new String[] {DwcTerm.PREFIX, DwcTerm.NS});
		if (term == null) {
			term = findTermInEnum(normTermName, DcTerm.values(),
					new String[] {DcTerm.PREFIX + ":", "http://purl.org/dc/elements/1.1/", "dct", "dcterm:", "dcterms:", DcTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, GbifTerm.values(),
					new String[] {GbifTerm.PREFIX, GbifTerm.NS});
		}
		if (term ==null) {
			term = findTermInEnum(normTermName, AcTerm.values(),
					new String[] {AcTerm.PREFIX, AcTerm.NS});
		}
		if (term ==null) {
			term = findTermInEnum(normTermName, ExtendedAcTerm.values(),
					new String[] {AcTerm.PREFIX, ExtendedAcTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, IucnTerm.values(),
					new String[] {IucnTerm.PREFIX, IucnTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, Wgs84Term.values(),
					new String[] {Wgs84Term.PREFIX, Wgs84Term.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, EmonocotTerm.values(),
					new String[] {EmonocotTerm.PREFIX, EmonocotTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, WCSPTerm.values(),
					new String[] {WCSPTerm.PREFIX, WCSPTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, SkosTerm.values(),
					new String[] {SkosTerm.PREFIX, SkosTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, ExifTerm.values(),
					new String[] {ExifTerm.PREFIX, ExifTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, Iptc4xmpTerm.values(),
					new String[] {Iptc4xmpTerm.PREFIX, Iptc4xmpTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, XmpRightsTerm.values(),
					new String[] {XmpRightsTerm.PREFIX, XmpRightsTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, XmpTerm.values(),
					new String[] {XmpTerm.PREFIX, XmpTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, IucnTerm.values(),
					new String[] {IucnTerm.PREFIX, IucnTerm.NS});
		}
		if (term == null) {
			term = findTermInEnum(normTermName, unkownTerms);
		}
		if (term == null) {
			term = UnknownTerm.build(termName);
			unkownTerms.add(term);
		}
		return term;
	}

@Override public Type adaptType(Type responseType, Metadata<Rx2Retrofit> metadata) {
    checkReturnMethodTypeIsSingleOrCompletable(metadata);

    if (!(responseType instanceof ParameterizedType)) return Object.class;

    ParameterizedType singleType = (ParameterizedType) responseType;

    if (isReturnMethodTypeResponse(metadata)) {
      ParameterizedType responseParameterizedType = (ParameterizedType)
          singleType.getActualTypeArguments()[0];
      Type enclosingType = responseParameterizedType.getActualTypeArguments()[0];
      return enclosingType;
    } else {
      Type enclosingType = singleType.getActualTypeArguments()[0];
      return enclosingType;
    }
  }

@Override public Object illegal(Metadata<Enum> metadata) {
    throwExceptionOnEmptyArray(metadata);

    String defaultOptional = metadata.getAnnotation().illegal();
    Type type = metadata.getType();

    if (!defaultOptional.isEmpty()) {
      return safetyCast.with(defaultOptional, metadata.getType());
    } else if (type.equals(String.class)) {
      return safetyCast.with("", type);
    } else {
      return safetyCast.with(0, type);
    }
  }

public MockeryMetadata fromParam(Class<?> mockingClass, Method method, Object[] args, int paramPosition) {
    Type typeParam = method.getGenericParameterTypes()[paramPosition];
    Annotation[] annotationsParam = method.getParameterAnnotations()[paramPosition];

    MockeryMetadata mockery = mockeryMetadata(mockingClass, method, args,
        typeParam, annotationsParam);

    return mockery;
  }

public Object with(Object object, Type type) {
    Class classType = (Class) type;

    if (classType.equals(int.class) || classType.equals(Integer.class)) {
      return Integer.valueOf(object.toString());
    } else if (classType.equals(long.class) || classType.equals(Long.class)) {
      return Long.valueOf(object.toString());
    } else if (classType.equals(float.class) || classType.equals(Float.class)) {
      return Float.valueOf(object.toString());
    } else if (classType.equals(double.class) || classType.equals(Double.class)) {
      return Double.valueOf(object.toString());
    } else if (classType.equals(String.class)) {
      return object.toString();
    }

    throw new RuntimeException("Type does not match any common java type");
  }

@Override public Call onIllegalMock(AssertionError assertionError, Metadata<Retrofit> metadata) {
    checkReturnMethodTypeIsCall(metadata);

    String errorMessage = assertionError.getMessage() != null ? assertionError.getMessage() : "";
    String safeErrorMessage = adaptErrorResponse(errorMessage, metadata);
    ResponseBody responseBody = ResponseBody
        .create(MediaType.parse("application/json"), safeErrorMessage);

    NetworkBehavior networkBehavior = networkBehaviour(metadata);
    return callAdapter.adapt(metadata.getMethod(),
        networkBehavior, Calls.response(Response.error(404, responseBody)));
  }

@Override
    public int read(char[] cbuf, int off, int len) throws IOException {
        if (off < 0) throw new IllegalArgumentException("off < 0");
        if (off >= cbuf.length) throw new IllegalArgumentException("off >= cbuf.length");
        if (len <= 0) throw new IllegalArgumentException("len <= 0");

        if (!this.preparedToRead) {
            prepareToRead();
        }

        int copyLen = this.inputText.length - cursor;
        if(copyLen < 1){
            initAttributes();
            return -1;
        }

        copyLen = copyLen > len ? len : copyLen;
        System.arraycopy(inputText, cursor, cbuf, off, copyLen);
        cursor += copyLen;
        return copyLen;
    }

