  public void close() {
    final DataFrame frame = new DataFrame();
    for (final String key : properties.keySet()) {
      try {
        frame.add(key, properties.get(key));
      } catch (final Exception e) {
        Log.debug("Cannot persist property '" + key + "' - " + e.getMessage());
      }
    }

    frame.put(Symbols.RUN_COUNT, runcount);

    final Object rundate = get(Symbols.DATETIME);
    if (rundate != null) {
      if (rundate instanceof Date) {
        frame.put(Symbols.PREVIOUS_RUN_DATETIME, rundate);
      } else {
        Log.warn(LogMsg.createMsg(CDX.MSG, "Context.run_date_reset", rundate));
      }
    }

    upsertFields(connection, TABLE_NAME, frame);

    DatabaseUtil.closeQuietly(connection);
    // connection = null; //should probably null this out since it is closed

    super.close();
  }

public static String unquote(String text) {
    if (text == null) {
      return null;
    }

    final int len = text.length();

    if (len < 2 || text.charAt(0) != '"' || text.charAt(len - 1) != '"') {
      return text;
    }

    text = text.substring(1, len - 1);

    return unescape(text);
  }

@Override
  public DataFrame process(final DataFrame frame) throws TransformException {
    DataFrame retval = frame;
    DataField field = retval.getField(getFieldName());

    if (field != null) {
      String format = getConfiguration().getString(ConfigTag.FORMAT);

      if (StringUtil.isNotBlank(format)) {
        String text = "";
        short type = field.getType();

        switch (type) {
          case DataField.DOUBLE:
            text = new DecimalFormat(format).format((double)field.getObjectValue());
            break;
          case DataField.FLOAT:
            text = new DecimalFormat(format).format((float)field.getObjectValue());
            break;
          case DataField.S64:
          case DataField.U32:
            text = NumberFormat.getInstance().format((long)field.getObjectValue());
            break;
          case DataField.S32:
          case DataField.U16:
            text = NumberFormat.getInstance().format((int)field.getObjectValue());
            break;
          case DataField.S16:
          case DataField.U8:
            text = NumberFormat.getInstance().format((short)field.getObjectValue());
            break;
          case DataField.DATE:
            text = new SimpleDateFormat(format).format((java.util.Date)field.getObjectValue());
            break;
          case DataField.STRING:
            if (UPPERCASE.equals(format)) {
              text = field.getStringValue();
              if (StringUtil.isNotBlank(text)) {
                text = text.toUpperCase();
              }
            } else if (LOWERCASE.equals(format)) {
              text = field.getStringValue();
              if (StringUtil.isNotBlank(text)) {
                text = text.toLowerCase();
              }
            } else {
              text = guess(field, format);
            }
            if (text == null) {
              Log.error("Data field '" + field.getName() + "' of type 'String' could not be converted into a formattable type - Value: '" + field.getStringValue() + "'");
            }
            break;
          default:
            Log.error("Data field '" + field.getName() + "' of type : " + field.getTypeName() + " cannot be formatted");
            break;
        }

        if (StringUtil.isNotBlank(text)) {
          retval.put(field.getName(), text);
        }
      } else {
        // no format...just get the string value of the field and place it back in the frame
        retval.put(field.getName(), field.getStringValue());
      }

    }
    // return the dataframe with its new date field
    return retval;
  }

