public static String unquote(String text) {
        if (text == null) {
            return null;
        }

        int len = text.length();

        if (len < 2 || text.charAt(0) != '"' || text.charAt(len - 1) != '"') {
            return text;
        }

        text = text.substring(1, len - 1);

        return unescape(text);
    }

